CREATE OR REPLACE FUNCTION public.get_profile_plan_badges_for_viewer(_viewer uuid,_ids uuid[]) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_object_agg(p.id::text,public.profile_plan_badge(p.id)) FILTER(WHERE public.profile_plan_badge(p.id) IS NOT NULL),'{}'::jsonb) FROM public.profiles p WHERE _viewer IS NOT NULL AND EXISTS(SELECT 1 FROM public.profiles WHERE id=_viewer AND is_active) AND p.id=ANY(_ids[1:2000]) AND public.subscriber_can_see(_viewer,p.id) $$;
REVOKE ALL ON FUNCTION public.get_profile_plan_badges_for_viewer(uuid,uuid[]) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.get_profile_plan_badges_for_viewer(uuid,uuid[]) TO service_role;